import{_ as l,c as e,o as i,ag as t}from"./chunks/framework.FgzfQ7Ey.js";const h=JSON.parse('{"title":"垃圾回收（Garbage Collection）","description":"","frontmatter":{},"headers":[],"relativePath":"js/garbage.md","filePath":"js/garbage.md","lastUpdated":1764505738000}'),o={name:"js/garbage.md"};function r(n,a,s,c,g,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="垃圾回收-garbage-collection" tabindex="-1">垃圾回收（Garbage Collection） <a class="header-anchor" href="#垃圾回收-garbage-collection" aria-label="Permalink to &quot;垃圾回收（Garbage Collection）&quot;">​</a></h1><h2 id="_1-概念定义" tabindex="-1">1. 概念定义 <a class="header-anchor" href="#_1-概念定义" aria-label="Permalink to &quot;1. 概念定义&quot;">​</a></h2><ul><li><strong>垃圾回收</strong>：JavaScript 自动管理内存的机制，通过回收不再使用的对象，释放内存空间，避免内存泄漏。</li></ul><h2 id="_2-产生原因-工作原理" tabindex="-1">2. 产生原因 / 工作原理 <a class="header-anchor" href="#_2-产生原因-工作原理" aria-label="Permalink to &quot;2. 产生原因 / 工作原理&quot;">​</a></h2><ul><li><strong>产生原因</strong>：开发者手动管理内存容易出错，容易造成内存泄漏。垃圾回收机制自动管理对象的生命周期。</li><li><strong>工作原理</strong>： <ul><li><strong>标记清除（Mark-and-Sweep）</strong>：从根对象（如全局对象）开始，标记所有可达对象，未被标记的对象则被回收。</li><li><strong>引用计数（Reference Counting）</strong>：每个对象维护引用计数，当计数为 0 时对象可被回收。</li></ul></li><li><strong>浏览器实现</strong>：现代 JavaScript 引擎主要采用标记清除法，结合增量和分代回收策略优化性能。</li></ul><h2 id="_3-典型示例" tabindex="-1">3. 典型示例 <a class="header-anchor" href="#_3-典型示例" aria-label="Permalink to &quot;3. 典型示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let obj = { name: &#39;Alice&#39; };</span></span>
<span class="line"><span>obj = null;  // obj 对象失去引用，可以被垃圾回收</span></span></code></pre></div><ul><li><strong>解释</strong>：<code>obj</code> 对象被赋值为 <code>null</code> 后，不再有任何引用指向它，垃圾回收机制会自动回收其占用的内存。</li></ul><h2 id="_4-应用场景" tabindex="-1">4. 应用场景 <a class="header-anchor" href="#_4-应用场景" aria-label="Permalink to &quot;4. 应用场景&quot;">​</a></h2><ul><li><strong>大型应用内存管理</strong>：确保不再使用的对象及时释放，防止内存泄漏。</li><li><strong>闭包和定时器</strong>：清理不再需要的闭包或定时器引用，避免内存占用持续增长。</li><li><strong>浏览器和 Node.js</strong>：JavaScript 运行环境中保证程序长时间运行不会耗尽内存。</li></ul><h2 id="_5-常见考点与陷阱" tabindex="-1">5. 常见考点与陷阱 <a class="header-anchor" href="#_5-常见考点与陷阱" aria-label="Permalink to &quot;5. 常见考点与陷阱&quot;">​</a></h2><ul><li><strong>内存泄漏常见原因</strong>： <ul><li>全局变量长期存在</li><li>闭包引用未清理</li><li>未清理的定时器、事件监听器</li></ul></li><li><strong>循环引用问题</strong>：引用计数机制无法处理循环引用，需要标记清除来解决。</li><li><strong>不确定性</strong>：垃圾回收执行时间不可预测，可能影响性能。</li></ul><h2 id="_6-优缺点总结" tabindex="-1">6. 优缺点总结 <a class="header-anchor" href="#_6-优缺点总结" aria-label="Permalink to &quot;6. 优缺点总结&quot;">​</a></h2><ul><li><strong>优点</strong>： <ul><li>自动管理内存，减少开发者负担；</li><li>降低内存泄漏风险；</li><li>提高程序安全性和稳定性。</li></ul></li><li><strong>缺点</strong>： <ul><li>垃圾回收时间不可控，可能造成短暂性能波动；</li><li>需要理解闭包和引用，避免间接造成内存泄漏。</li></ul></li></ul><h2 id="_7-一句话总结" tabindex="-1">7. 一句话总结 <a class="header-anchor" href="#_7-一句话总结" aria-label="Permalink to &quot;7. 一句话总结&quot;">​</a></h2><ul><li>JavaScript 的垃圾回收机制通过标记清除和引用计数自动管理内存，帮助开发者减少内存泄漏风险。</li></ul>`,16)])])}const _=l(o,[["render",r]]);export{h as __pageData,_ as default};
